ddRoute( $this );	}		public function getIpcServer( 		DwCallBack $onConnect		,\bakuba\kernel\process\iDwProcessIpc $dwProcessIpc	) : self {		$dwIpcServer = new self( $this->getDwIpcSelect() ,$onConnect ,$dwProcessIpc );//,$this );		//$dwIpcSelect->addRoute( $this );		//$this->getDwIpcSelect()->addRoute( $dwIpcServer );		return $dwIpcServer;	}		public function init(  ) : void {		//parent::init();		$this->log->trace( "." );		$this->listenStart();	}		public function connect( DwIpcKey $dwIpcKeyDst ) : \bakuba\kernel\io\ipc\DwIpcMsg {		$dwIpcMsg = new DwIpcMsg( $this->dwIpcKey );		$dwIpcMsg->destination( $dwIpcKeyDst );		//$this->log->trace(".");		return $dwIpcMsg;	}	protected $isListen = false;	protected function listenStart( ) {		if ( $this->isListen )			throw new \Exception("is ever in listen");		else			$this->listen();	}	///*	protected function listen() : void {		$iDwLogger = null;		if ( \method_exists( $this->log ,"upTo" ) )			$iDwLogger = $this->log->upTo( $this ,"listen" );		else			$iDwLogger = $this->log;		$dwIpc = new DwIpc( $this ,$this->dwIpcKey );		$dwIpc->enableListen();		//$iDwLogger->trace("listen");		//$dwResource->listenTo( $this->dwPort );		$dwIpc->setOnReaded( new DwCallBack ( array( &$this ,"ipcAcceptConnection" ) ,$dwIpc ) );		$this->getDwIpcSelect()->ipcRead( $dwIpc );		$this->log->debug( "-listen" );		$this->isListen = true;	}	//*/	public function ipcAcceptConnection( DwIpc $dwIpcAccept ) : void {		$this->log->trace(".");		$dwIpcMsg = $dwIpcAccept->read();		$dwIpc = new DwIpc( $this ,$dwIpcMsg->getSrcKey() );		$dwIpc->write( $dwIpcMsg );		$this->newIpcConnection( $dwIpc );				//$dwIpcAccept->setOnReaded( new DwCallBack( array( &$this ,"ipcAcceptConnection" ), $dwIpcAccept ) );		$this->getDwIpcSelect()->ipcRead( $dwIpcAccept );	}	protected function ipcConnexion( DwIpc $dwIpc ) : DwIpcConnexion {		return	new DwIpcConnexion (			$this->getDwIpcSelect()			,$dwIpc		);	}	public function newIpcConnection( DwIpc $dwIpc ) : void {		$this->log->info( " Try IPC" );		$this->getDwIpcSelect()->getDwObjectTimer()->addTick(			$this->onConnect->getClone( $this->ipcConnexion( $dwIpc ) )		);	}	///*	private $listCallBack = array();	public function msgWrite(		DwIpcMsg $dwIpcMsg		,DwCallBack $onWrited = null	) : void {		$this->log->trace( "".$dwIpcMsg->getDstKey() );		$dwIpc = new DwIpc( $this ,$dwIpcMsg->getDstKey() );		$dwIpc->write( $dwIpcMsg );		if ( \is_object( $onWrited ) )			$dwIpc->setOnWrited( $onWrited );		$this->getDwIpcSelect()->ipcWrite( $dwIpc );	}	//*/	///*	public function __destruct() {		//$this->log->trace( "." );		parent::__destruct();		foreach( $this as $key => $toDestruct )			if ( isset( $this->$key ) ) unset( $this->$key );	}	//*/	public function getClassName( bool $fqcn=null ) : string {		return self::getStaticClassName( $fqcn );	}	public static function getStaticClassName( bool $fqcn=null ) : string {		return $fqcn ? parent::getStaticClassName( $fqcn ).self::CLASS_SEPARATOR.__CLASS__ : __CLASS__;	}}?>